import {esc,icon} from './ui.mjs';
import {parseDocument,countChars} from '../precheck/engine.mjs';
import {publicWebQueryPlan} from '../precheck/web-query-plan.mjs';
import {withStableView} from './view-stability.mjs';
import {reportHtml} from '../precheck/export.mjs';
import {exportGeneratedFile} from './artifact-export.mjs';
import {importWorkspaceDocument} from './document-import.mjs';
import {createDocumentServiceClient,watchDocumentService} from './document-services-client.mjs';
const active=item=>['queued','running'].includes(item?.status);
const statusLabel={queued:'排队中',running:'正在处理',completed:'来源比对完成',failed:'未完成',cancelled:'已取消'};
const stages={queued:'等待检索',reading_input:'读取待检正文',checking_input:'确认检索内容',reading_sources:'读取来源正文',saving_report:'保存证据报告',searching:'查找公开来源',search:'查找公开来源',fetching:'读取来源正文',fetch:'读取来源正文',comparing:'逐字比对正文',compare:'逐字比对正文',reporting:'整理证据报告',completed:'来源比对完成'};
const safeId=id=>typeof id==='string'&&/^[A-Za-z0-9_-]{1,100}$/.test(id);
const publicError=message=>Object.assign(Error(message),{publicMessage:message});
export function webSimilarityError(error){if(error.publicMessage)return error.publicMessage;if(error.status===401)return '登录已失效，请重新登录；已提交的任务仍保留在原账户。';if(error.status===429)return '今日使用次数已达上限，请稍后再试。';if(error.status===413)return '正文超过当前单次限制，请缩短后重新确认。';if([400,422].includes(error.status))return '正文或提交信息不符合要求，请核对后重新确认。';if(error.status===503)return '联网来源查重暂不可用，请稍后再试；本地材料比对仍可使用。';return '请求暂未完成，请先读取原任务或最近任务，避免重复提交。';}
export function validateWebText(text,cap={}){const characters=Array.from(String(text||'')).length,max=Math.min(20000,Number(cap.maxCharacters)||20000);if(!String(text||'').trim()||characters<40)throw publicError('请提供至少 40 个字符的论文正文。');if(characters>max)throw publicError(`正文超过 ${max.toLocaleString('zh-CN')} 字符，不会自动截断；请缩短后重试。`);return {text,characters};}
export function previewWebText(text,cap={}){
 const value=validateWebText(text,cap),parsed=parseDocument(value.text,'检测正文'),included=parsed.sections.filter(section=>!section.excluded),paragraphs=included.flatMap(section=>section.paragraphs),characters=paragraphs.reduce((n,p)=>n+countChars(p.text),0),plan=publicWebQueryPlan(parsed,3);
 if(characters<40)throw publicError('请提供至少 40 个有效正文字符，不含标点、空白与固定排除章节。');
 if(paragraphs.length>300)throw publicError('本次正文超过 300 段，请按章节提交。');
 if(!plan.queries.length)throw publicError('尚无可检索的完整段落。请将相关短句合并为至少 32 个有效字符的自然段，再核对正文。');
 return {...value,parsed,characters,plan};
}
export function ensureWebSimilarityStyle(doc=document){if(doc.querySelector('[data-web-similarity-style]'))return;const link=doc.createElement('link');link.rel='stylesheet';link.href='/workspace/web-similarity.css';link.dataset.webSimilarityStyle='';doc.head.append(link);}
export function mountWebSimilarity({container,fetchImpl,uuid=()=>crypto.randomUUID(),pollInterval=2400,reportId='',importDocument=importWorkspaceDocument,exportFile=exportGeneratedFile}={}){
 const doc=container.ownerDocument,win=doc.defaultView,$=s=>container.querySelector(s);let alive=true,blocked=false,epoch=0,ownerId=null,cap={},busy=false,importing=false,intent=null,item=null,report=null,recent=[],timer=null,preview=null,unwatch=()=>{},submittedText='',pendingImport=null,importController=null,inputMode='upload';const mountHash=win.location.hash;const current=()=>alive&&container.isConnected,client=createDocumentServiceClient({fetchImpl,isCurrent:current});ensureWebSimilarityStyle(doc);
 function stop(){if(timer!==null)win.clearTimeout(timer);timer=null;}
 function closePreview(){if(!preview)return;preview.querySelector('iframe').srcdoc='';preview.remove();preview=null;}
 function dispose(){if(!alive)return;alive=false;epoch++;stop();closePreview();importController?.abort();pendingImport=null;client.dispose();unwatch();removeSessionWatch();}
 unwatch=watchDocumentService(container,dispose);
 const sessionCheck=()=>{if(ownerId&&current()&&!blocked)void checkOwner().catch(error=>{if(current()&&error.name!=='AbortError')status(webSimilarityError(error),true);});};win.addEventListener('storage',sessionCheck);win.addEventListener('focus',sessionCheck);
 const hasDraft=()=>!!($('[data-web-text]')?.value.trim()&&$('[data-web-text]').value!==submittedText)||importing||!!pendingImport;
 const beforeUnload=event=>{if(current()&&!blocked&&hasDraft()){event.preventDefault();event.returnValue='';}};win.addEventListener('beforeunload',beforeUnload);
 function canLeave(){if(!current()||blocked||!hasDraft())return true;if(win.location.hash===mountHash)return false;return win.confirm('当前正文尚未提交，也未保存到浏览器。离开会丢失本页未提交的正文或导入结果，是否离开？');}
 const removeSessionWatch=()=>{win.removeEventListener('beforeunload',beforeUnload);win.removeEventListener('storage',sessionCheck);win.removeEventListener('focus',sessionCheck);};
 function status(message,error=false){const node=$('[data-web-status]');if(node){node.textContent=message;node.classList.toggle('is-error',error);node.setAttribute('role',error?'alert':'status');}}
 function clearOwner(){blocked=true;epoch++;client.dispose();stop();closePreview();importController?.abort();pendingImport=null;item=null;report=null;intent=null;recent=[];submittedText='';for(const selector of ['[data-web-text]','[data-web-title]'])if($(selector))$(selector).value='';if($('[data-web-consent]'))$('[data-web-consent]').checked=false;renderResult();renderRecent();countInput();}
 function assertCurrent(version=epoch){if(!current()||blocked||version!==epoch)throw new DOMException('页面或账户上下文已失效','AbortError');}
 async function request(...args){const version=epoch;assertCurrent(version);const result=await client.request(...args);assertCurrent(version);return result;}
 async function checkOwner(){const version=epoch;assertCurrent(version);const me=await request('/auth/me');assertCurrent(version);if(!me.user?.id){clearOwner();throw Object.assign(Error('login required'),{status:401});}if(me.user.id!==ownerId){clearOwner();throw publicError('登录账户已变化，原账户正文和结果已隐藏。请重新进入本功能。');}assertCurrent(version);return me.user;}
 function assertResponseOwner(value){assertCurrent();if(value?.ownerId!==ownerId){clearOwner();throw publicError('任务所属账户无法核对，结果已隐藏，请重新进入本功能。');}return value;}
 function updateControls(){if(!$('[data-web-text]'))return;const locked=busy||blocked||Boolean(intent)||active(item)||item?.status==='completed'&&!report;container.setAttribute('aria-busy',String(busy||importing));for(const selector of ['[data-web-text]','[data-web-title]','[data-web-consent]'])$(selector).disabled=locked;$('[data-web-file]').disabled=locked||importing;let valid=false;try{previewWebText($('[data-web-text]').value,cap);valid=true;}catch{}$('[data-web-start]').disabled=locked||importing||!cap.ready||!$('[data-web-consent]').checked||!valid;$('[data-web-refresh]').disabled=busy||blocked||importing;$('[data-web-refresh]').hidden=!item;$('[data-web-retry]').hidden=!intent||Boolean(item);$('[data-web-retry]').disabled=busy||blocked;$('[data-web-new]').hidden=!item||active(item)||item.status==='completed'&&!report;$('[data-web-new]').disabled=busy||blocked||importing;container.querySelectorAll('[data-web-recent-id],[data-web-preview],[data-web-download],[data-web-cancel]').forEach(button=>button.disabled=busy||blocked||importing||Boolean(intent));container.querySelectorAll('[data-web-input-mode],[data-web-adopt-import],[data-web-discard-import]').forEach(button=>button.disabled=busy||blocked||importing||Boolean(intent)||active(item));preview?.querySelectorAll('[data-web-print],[data-web-preview-download]').forEach(button=>button.disabled=busy||blocked);}
 function countInput(){const node=$('[data-web-text]');if(!node)return;$('[data-web-counter]').textContent=`${Array.from(node.value).length.toLocaleString('zh-CN')} / ${(Number(cap.maxCharacters)||20000).toLocaleString('zh-CN')} 字符`;const scope=$('[data-web-scope]');if(scope){if(!node.value.trim()){scope.innerHTML='<p>填写正文后，在这里核对实际参与检测的章节与有效字符。</p>';}else{try{const {parsed,characters,plan}=previewWebText(node.value,cap);scope.innerHTML=`<p><b>${characters.toLocaleString('zh-CN')}</b> 个有效正文字符 · ${plan.totalParagraphs} 段 · 将抽样 ${plan.sampledParagraphs} 段，最多 ${plan.queries.length} 次检索</p><details><summary>核对章节与固定排除范围</summary><ul>${parsed.sections.map(section=>`<li><span>${esc(section.title)}</span><small>${section.excluded?'固定排除':section.paragraphs.reduce((n,p)=>n+countChars(p.text),0)+' 个有效字符 · 参与比对'}</small></li>`).join('')}</ul><p>目录、参考文献、致谢、附录固定排除；如仅检测部分章节，请在正文中保留需要检测的内容。</p></details>`;}catch(error){scope.innerHTML=`<p class="web-similarity-scope-error">${esc(error.publicMessage||'请核对正文格式与章节。')}</p>`;}}}updateControls();}
 function setInputMode(mode){inputMode=mode;container.querySelectorAll('[data-web-input-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.webInputMode===mode)));$('[data-web-upload-panel]').hidden=mode!=='upload';$('[data-web-paste-label]').textContent=mode==='upload'?'提取的正文 · 可继续核对修改':'需要核对的正文';}
 function showPendingImport(){const node=$('[data-web-pending-import]');node.hidden=!pendingImport;node.innerHTML=pendingImport?'<p>导入期间正文已修改。你的当前编辑已保留，提取结果尚未替换正文。</p><button class="btn secondary" type="button" data-web-adopt-import>采用这次提取结果</button><button class="btn secondary" type="button" data-web-discard-import>保留当前编辑</button>':'';$('[data-web-adopt-import]')?.addEventListener('click',()=>{if(!pendingImport||!win.confirm('采用提取结果会替换当前正文，是否继续？'))return;adoptImport(pendingImport);});$('[data-web-discard-import]')?.addEventListener('click',()=>{pendingImport=null;showPendingImport();});}
 function adoptImport(value){$('[data-web-text]').value=value.text;if(!$('[data-web-title]').value.trim())$('[data-web-title]').value=value.title;pendingImport=null;showPendingImport();$('[data-web-consent]').checked=false;countInput();status('正文已提取，请核对章节与正文并确认联网检索授权，尚未提交查重。');}
 function persist(){if(!ownerId||!item)return;try{win.localStorage.setItem('paperknow-web-similarity-last:'+ownerId,JSON.stringify({itemId:item.id}));}catch{status('任务已保存到账户，本机恢复标记未能保存；可从最近任务继续。',true);}}
 function renderRecent(){const node=$('[data-web-recent]');if(!node)return;node.innerHTML=`<h3>检测记录与报告</h3><p class="web-similarity-history-note">读取原任务不会重新检索；完成后可预览、下载报告。</p>${recent.length?recent.slice(0,8).map(row=>`<button type="button" data-web-recent-id="${esc(row.id)}"><span><b>${esc(row.title||'未命名文稿')}</b><small>${esc(statusLabel[row.status]||'已记录')} · ${(Number(row.characters)||0).toLocaleString('zh-CN')} 字符</small></span>${icon('arrow',14)}</button>`).join(''):'<p>提交后可在这里恢复任务，不需要重新发送正文。</p>'}`;node.querySelectorAll('[data-web-recent-id]').forEach(button=>button.onclick=()=>{if(hasDraft()&&!win.confirm('读取历史会切换当前任务；当前未提交正文仍保留在输入框中，是否继续？'))return;void command(()=>read(button.dataset.webRecentId));});updateControls();}
 function coverage(value){const web=value?.web||value?.coverage||{},n=key=>Number.isFinite(Number(web[key]))?Math.max(0,Number(web[key])):0;return {web,sampled:n('sampledParagraphs'),total:n('totalParagraphs'),fetched:n('fetchedSources'),failed:n('failedSources'),candidates:n('candidateSources'),queries:n('queries')};}
 function renderResult(){const target=$('[data-web-result]');if(!target)return;if(!item){target.hidden=true;target.innerHTML='';return;}const c=coverage(report||item),done=item.status==='completed'&&report&&c.fetched>0,limited=c.failed>0||c.web.searchComplete===false;withStableView(container.closest('.dashboard')||container,()=>{target.hidden=false;target.innerHTML=`<header class="web-similarity-result-head"><div><span class="web-similarity-eyebrow">${active(item)?'处理中 · 可稍后回来':'PAPERKNOW 来源证据'}</span><h3>${esc(stages[item.stage]||statusLabel[item.status]||'任务状态')}</h3></div><span class="web-similarity-state ${item.status==='failed'?'is-error':''}">${esc(statusLabel[item.status]||'已记录')}</span></header>${done?`<div class="web-similarity-metrics"><div><small>重复率 · 本次实际来源范围</small><strong>${(Number(report.ratio)*100).toFixed(1)}<em>%</em></strong><p>${limited?'本次检索或来源读取范围受限':'仅针对本次实际取得的来源正文'}</p></div><div><small>实际取得来源</small><b>${c.fetched} <em>份</em></b><p>${c.failed} 份未能取得</p></div><div><small>抽样检索段落</small><b>${c.sampled} <em>/ ${c.total}</em></b><p>取得的来源与参与检测的全文逐字比对</p></div></div><p class="web-similarity-result-note">${Number(report.ratio)===0?'本次取得的来源内未发现符合规则的文字匹配；不代表不存在重复。':'相似字符按原文位置合并去重；请核对高亮、引用和实际来源。'} 本报告不覆盖全部互联网、付费全文或学校数据库。</p>${c.web.limitations?.length?`<ul class="web-similarity-limitations">${c.web.limitations.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:''}<div class="web-similarity-actions"><button class="btn secondary" type="button" data-web-preview>预览检测报告 / 保存 PDF</button><button class="btn primary" type="button" data-web-download>下载完整检测报告</button>${Number(report.similarChars)>0?`<a class="btn secondary" href="#category/reduce?comparisonReport=${encodeURIComponent(item.id)}">按重复来源降重 ${icon('arrow',14)}</a>`:''}</div>`:item.status==='completed'&&!report?'<p class="web-similarity-result-note">任务已完成，报告暂时无法读取。请点击“读取任务状态”重试读取原报告，无需重新提交或重新检索。</p>':active(item)?`<ol class="web-similarity-progress">${['抽样检索','取得来源正文','全文逐字比对','整理证据'].map((value,index)=>`<li><span>0${index+1}</span>${value}</li>`).join('')}</ol><p>任务已保存在当前账户，离开页面不会重复创建任务；处理中不展示未经核对的相似占比。</p><button class="btn secondary" type="button" data-web-cancel>取消本次任务</button>`:`<p class="web-similarity-result-note">${item.status==='cancelled'?'任务已停止，未生成检测结论。':'本次任务未完成，未生成相似占比或检测结论。为避免重复外部检索，同一正文和标题在 24 小时内可能返回原任务；不会自动重试。请保留正文，可改用自备材料比对。'}</p>`}`;});$('[data-web-preview]')?.addEventListener('click',()=>void command(showReport));$('[data-web-download]')?.addEventListener('click',()=>void command(downloadReport));$('[data-web-cancel]')?.addEventListener('click',()=>void command(cancel));updateControls();}
 function renderForm(){container.innerHTML=`<div class="web-similarity"><section class="web-similarity-card"><header class="web-similarity-head"><span>${icon('search',26)}</span><div><span class="web-similarity-eyebrow">PUBLIC SOURCE CHECK</span><h2>论文重复率检测</h2><p>AI 辅助查找公开网页，只用实际取得的正文计算文字相似占比。</p></div></header><ol class="detection-flow-steps" aria-label="联网查重步骤"><li>1 准备正文</li><li>2 核对范围与授权</li><li>3 查看证据报告</li></ol><label class="web-similarity-label" for="web-similarity-title">文稿标题</label><input id="web-similarity-title" data-web-title maxlength="200" placeholder="例如：生成式人工智能在教学中的应用研究"><div class="detection-input-tabs" role="group" aria-label="正文输入方式"><button type="button" data-web-input-mode="paste" aria-pressed="true">粘贴文本</button><button type="button" data-web-input-mode="upload" aria-pressed="false">上传文档</button></div><div class="detection-upload-panel" data-web-upload-panel hidden><label class="web-similarity-file">${icon('upload',24)}<span><b>选择 TXT / DOCX / PDF</b><small>TXT / DOCX 最大 50MB，本地提取；PDF 最大 20MB，云解析单独确认</small></span><input data-web-file type="file" accept=".txt,.docx,.pdf" aria-label="导入待查重文档"></label><p>文件仅用于提取正文。提取完成后仍需核对与授权，才会提交检测。不支持的旧版 DOC 请先另存为 DOCX。</p></div><label class="web-similarity-label" data-web-paste-label for="web-similarity-text">需要核对的正文</label><textarea id="web-similarity-text" data-web-text rows="12" placeholder="粘贴论文正文。确认后才会提交，不会自动发送或截断。"></textarea><div class="detection-pending-import" data-web-pending-import hidden></div><div class="web-similarity-input-meta"><span>TXT / DOCX 本地提取；PDF 云解析需另行确认</span><span data-web-counter></span></div><section class="detection-scope-preview" aria-label="参与检测的正文范围"><h3>核对检测范围</h3><div data-web-scope></div></section>${cap.bundleUsageSupported?'<p class="section-hint" data-detection-bundle-note>本次不扣积分；如已购套餐包含对应检测次数，将记录一次套餐使用，失败或取消会释放预占次数。</p>':''}<div class="web-similarity-consent"><input id="web-similarity-consent" data-web-consent type="checkbox"><label for="web-similarity-consent">我有权处理这些内容，同意将正文提交本服务，并将有限的文本片段用于外部联网检索；已了解仅比对本次可访问的公开来源，未发现匹配不代表不存在重复。</label></div><div class="web-similarity-actions"><button class="btn primary" type="button" data-web-start>${icon('search',16)} 开始重复率检测</button><button class="btn secondary" type="button" data-web-refresh hidden>读取任务状态</button><button class="btn secondary" type="button" data-web-retry hidden>读取原提交</button><button class="btn secondary" type="button" data-web-new hidden>检测另一篇论文</button></div><p class="web-similarity-status" data-web-status role="status" aria-live="polite">确认授权后才会发送正文。试用期间不扣积分。</p><section data-web-result class="web-similarity-result" hidden aria-label="联网来源查重结果"></section></section><aside class="web-similarity-side"><section class="web-similarity-card"><span class="web-similarity-eyebrow">有范围 · 有证据</span><h3>每个结果都能回到来源</h3><dl><div><dt>单次正文</dt><dd>最多 ${(Number(cap.maxCharacters)||20000).toLocaleString('zh-CN')} 字符</dd></div><div><dt>检索范围</dt><dd>最多 ${Number(cap.maxQueries)||3} 段抽样检索</dd></div><div><dt>候选来源</dt><dd>最多 ${Number(cap.maxSources)||8} 份</dd></div><div><dt>每日试用</dt><dd>每账户 ${Number(cap.userDailyLimit)||3} 次 · 免费</dd></div></dl><p>搜索结果摘要不直接计入相似占比。只有取得的真实来源正文参与逐字比对。</p><p>受检索排名、网页权限和访问状态影响，报告会注明抽样段落数、取得和失败来源数。</p><a class="web-similarity-link" href="#category/detection?view=local">已有对照材料？使用本地比对 →</a></section><section class="web-similarity-card web-similarity-recent" data-web-recent></section><section class="web-similarity-card detection-faq"><h3>常见问题</h3><details><summary>这是学校数据库查重吗？</summary><p>这是公开网页来源比对，不接通知网、维普、万方，也不出具这些机构的检测报告。</p></details><details><summary>没有匹配是否表示可以提交？</summary><p>只能说明本次实际取得的来源内未发现符合规则的匹配。请继续核对引用、学校要求和未覆盖的材料。</p></details><details><summary>失败后是否会自动重复检索？</summary><p>不会。请先读取原任务。相同正文和标题在 24 小时内可能返回原记录，以避免重复消耗外部检索。</p></details><details><summary>正文会保存在本机吗？</summary><p>本页未提交正文只在当前页面内存中保留。提交后的任务和报告保存在当前账户；本机仅记住任务编号。</p></details></section></aside></div>`;for(const selector of ['[data-web-text]','[data-web-title]'])$(selector).oninput=()=>{$('[data-web-consent]').checked=false;countInput();};$('[data-web-consent]').onchange=updateControls;$('[data-web-start]').onclick=()=>void command(submit);$('[data-web-refresh]').onclick=()=>void command(()=>read(item.id));$('[data-web-retry]').onclick=()=>void command(sendIntent);$('[data-web-new]').onclick=()=>{item=null;report=null;closePreview();$('[data-web-consent]').checked=false;renderResult();countInput();status('请核对正文并重新确认授权，再开始新的查重。');};container.querySelectorAll('[data-web-input-mode]').forEach(button=>button.onclick=()=>setInputMode(button.dataset.webInputMode));$('[data-web-file]').onchange=()=>void importFile();setInputMode(inputMode);renderRecent();countInput();}
 async function recentItems(){const value=await request('/web-similarity');await checkOwner();assertResponseOwner(value);recent=(value.items||[]).filter(v=>safeId(v.id)&&Object.hasOwn(statusLabel,v.status));renderRecent();}
 function schedule(){stop();if(current()&&active(item))timer=win.setTimeout(()=>void command(()=>read(item.id)),pollInterval);}
 async function accept(value){assertCurrent();if(!safeId(value?.id)||!Object.hasOwn(statusLabel,value.status))throw publicError('任务状态无法核对，请先读取最近任务。');closePreview();item=value;report=null;intent=null;recent=[value,...recent.filter(row=>row.id!==value.id)];persist();if(value.status==='completed'){let response;try{response=await request('/web-similarity/'+encodeURIComponent(value.id)+'/report');}catch(error){if(error.name==='AbortError')throw error;throw publicError('任务已完成，但报告暂时无法读取；请读取原任务状态，无需重新提交。');}await checkOwner();assertResponseOwner(response);if(response.report?.mode!=='web'||!Number.isFinite(response.report?.ratio)||!Array.isArray(response.report?.sections))throw publicError('报告内容尚未就绪，请稍后读取任务状态。');report=response.report;}renderResult();renderRecent();schedule();}
 async function read(id){if(!safeId(id))throw publicError('任务编号无效，请从最近记录重新选择。');stop();await checkOwner();const value=await request('/web-similarity/'+encodeURIComponent(id));await checkOwner();assertResponseOwner(value);await accept(value.item);status(active(item)?'任务已保存，正在自动读取进度，无需重新提交。':'已读取本次任务；请同时核对来源范围与正文证据。');}
 async function sendIntent(){if(!intent)return;await checkOwner();let value;try{value=await request('/web-similarity',{text:intent.text,title:intent.title,consent:true,expectedUserId:ownerId,idempotencyKey:intent.key});}catch(error){if([400,413,422,429].includes(error.status)){intent=null;$('[data-web-consent]').checked=false;}throw error;}await checkOwner();assertResponseOwner(value);const acceptedText=intent.text;await accept(value.item);submittedText=acceptedText;status(active(item)?'任务已加入队列，可离开页面稍后回来查看。':item.status==='completed'?'本次来源比对已完成，请查看实际范围。':item.status==='failed'?'已读取同一正文的原失败任务；24 小时内不会自动重复检索，可查看说明或使用本地材料比对。':'已读取原任务状态，未重新检索。');}
 async function submit(){if(!cap.ready||cap.pointsCharged!==false)throw publicError('联网查重当前未开放或费用信息不完整，不会提交任务。');if(!$('[data-web-consent]').checked)throw publicError('请先确认正文处理和联网检索授权。');const value=previewWebText($('[data-web-text]').value,cap);await checkOwner();intent={text:value.text,characters:value.characters,title:$('[data-web-title]').value.trim()||'未命名文稿',key:uuid()};item=null;report=null;renderResult();await sendIntent();}
 async function cancel(){if(!active(item))return;await checkOwner();const value=await request('/web-similarity/'+encodeURIComponent(item.id)+'/cancel',{expectedUserId:ownerId});await checkOwner();assertResponseOwner(value);await accept(value.item);status('已请求取消任务；已经发出的来源请求可能仍在结束。');}
 async function importFile(){if(busy||blocked||importing||intent||active(item))return;const node=$('[data-web-file]'),file=node.files?.[0];if(!file)return;node.value='';if(file.size>50*1024*1024||!/\.(txt|docx|pdf)$/i.test(file.name))return status('请选择不超过 50MB 的 TXT、DOCX 或 PDF 文档；PDF 云解析上限为 20MB。',true);if($('[data-web-text]').value.trim()&&!win.confirm('导入新文档会替换当前正文，是否继续？取消将保留当前编辑。'))return;const originalText=$('[data-web-text]').value,version=epoch;importController=new AbortController();importing=true;updateControls();try{await checkOwner();const extracted=await importDocument(file,$('[data-web-status]'),{signal:importController.signal});assertCurrent(version);await checkOwner();validateWebText(extracted.text,cap);const value={text:extracted.text,title:file.name.replace(/\.[^.]+$/,'').slice(0,200)};if($('[data-web-text]').value!==originalText){pendingImport=value;showPendingImport();status('当前编辑已保留，请选择是否采用本次提取结果。');}else adoptImport(value);}catch(error){if(current()&&error.name!=='AbortError')status(error.name==='DocumentImportCancelled'?'已取消导入，当前正文已保留。':webSimilarityError(error),true);}finally{if(current()){importing=false;importController=null;updateControls();}}}
 function reportContent(){assertCurrent();if(!report||!item||item.status!=='completed'||coverage(report).fetched<1)throw publicError('尚无完整的实际来源比对报告，不能导出相似占比。');return reportHtml(report);}
 async function showReport(){await checkOwner();const content=reportContent();closePreview();const dialog=doc.createElement('dialog');preview=dialog;dialog.className='web-similarity-preview';dialog.setAttribute('aria-label','PaperKnow 联网来源查重报告预览');dialog.innerHTML='<header><div><strong>PaperKnow 论文重复率检测报告</strong><p>报告包含范围、实际正文标注和来源对照。</p></div><button class="btn secondary" type="button" data-web-preview-download>下载 HTML</button><button class="btn primary" type="button" data-web-print>打印 / 保存 PDF</button><button class="btn secondary" type="button" data-web-close>关闭</button></header><iframe title="PaperKnow 联网来源查重报告" sandbox="allow-same-origin allow-modals" referrerpolicy="no-referrer"></iframe>';const frame=dialog.querySelector('iframe');frame.srcdoc=content;dialog.querySelector('[data-web-close]').onclick=closePreview;dialog.querySelector('[data-web-preview-download]').onclick=()=>void command(downloadReport);dialog.querySelector('[data-web-print]').onclick=()=>void command(async()=>{await checkOwner();if(preview!==dialog||!dialog.isConnected)return;frame.contentWindow.focus();frame.contentWindow.print();status('已请求打印，请在系统窗口中选择保存 PDF。');});dialog.addEventListener('cancel',e=>{e.preventDefault();closePreview();});dialog.addEventListener('close',closePreview,{once:true});doc.body.append(dialog);if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}
 async function downloadReport(){await checkOwner();const content=reportContent(),originalOwner=ownerId,reportItem=item;const guardedFetch=async(path,options)=>{if(!current()||blocked||ownerId!==originalOwner)throw publicError('账户或页面已变化，已停止导出。');if(path==='/api/auth/me'){await checkOwner();return new Response(JSON.stringify({user:{id:originalOwner}}),{status:200,headers:{'Content-Type':'application/json'}});}const response=await(fetchImpl||globalThis.fetch)(path,options);if(/^\/api\/artifacts\/[^/]+\/download\?/.test(path)&&response.ok){const bytes=await response.blob();await checkOwner();if(!current()||blocked||ownerId!==originalOwner)throw publicError('账户或页面已变化，已停止下载。');return new Response(bytes,{status:response.status,headers:response.headers});}return response;};const value=await exportFile({name:`PaperKnow-联网来源查重报告-${reportItem.id}.html`,content,type:'text/html;charset=utf-8',sourceType:'detection',sourceId:reportItem.id},{fetchImpl:guardedFetch,documentObject:doc});await checkOwner();status(value.message||'报告已保存并发起下载。');}
 async function command(fn){if(busy||!current()||blocked)return;busy=true;updateControls();try{await fn();}catch(error){if(current()&&error.name!=='AbortError'){if(error.status===401)clearOwner();else if(item)renderResult();status(webSimilarityError(error),true);}}finally{if(current()){busy=false;updateControls();}}}
 const ready=(async()=>{const version=epoch;container.innerHTML='<p role="status">正在确认联网来源查重与账户状态…</p>';try{const [me,capabilities]=await Promise.all([request('/auth/me'),request('/capabilities')]);assertCurrent(version);ownerId=me.user?.id||null;cap=capabilities.webSimilarity||{};if(!ownerId||!cap.ready||cap.pointsCharged!==false){container.innerHTML=`<section class="web-similarity-card"><h2>${!ownerId?'登录后使用联网来源查重':!cap.ready?'联网来源查重暂未开放':'服务费用待确认'}</h2><p>${!ownerId?'检索与报告仅在当前账户保存，请先登录。':'暂不提交任何正文；可继续使用本地材料比对。'}</p>${!ownerId?`<a class="btn primary" href="/auth.html?mode=login&next=${encodeURIComponent('/workspace.html'+win.location.hash)}">登录账户</a>`:''}<a class="btn secondary" href="#category/detection?view=local">本地材料比对</a></section>`;return;}renderForm();await recentItems();let stored;try{stored=JSON.parse(win.localStorage.getItem('paperknow-web-similarity-last:'+ownerId)||'null');}catch{}const id=safeId(reportId)?reportId:recent.find(row=>row.id===stored?.itemId)?.id||recent.find(active)?.id;if(id)await command(()=>read(id));}catch(error){if(current()&&error.name!=='AbortError'){if($('[data-web-status]'))status(webSimilarityError(error),true);else container.innerHTML=`<section class="web-similarity-card"><h2>暂时无法读取服务</h2><p role="alert">${esc(webSimilarityError(error))}</p><a href="#category/detection?view=local">使用本地材料比对</a></section>`;}}})();
 return {ready,dispose,canLeave,refresh:()=>command(()=>item?read(item.id):recentItems())};
}
